import{_ as i}from"./chunks/academic-universal-verifier.Caxxbpav.js";import{_ as a,C as s,o as r,c as n,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Digital Employee Academic Observation 002 — Completion Is a Claim, Not an Accepted State","description":"","frontmatter":{"title":"Digital Employee Academic Observation 002 — Completion Is a Claim, Not an Accepted State","date":"2026-08-05","column":"digital-employee","category":"academic","summary":"Microsoft Research’s Universal Verifier shows why a computer-use Digital Employee should submit separately inspectable process, outcome, failure and side-effect evidence before an independent authority accepts completion.","sources":["Microsoft Research and arXiv paper 2604.06240","Microsoft Research technical article","microsoft/fara Universal Verifier implementation","microsoft/CUAVerifierBench dataset card"],"outline":"deep","cover":"/assets/covers/universal-verifier-completion-contract-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-05-universal-verifier-completion-contract.md","filePath":"en/digital-employee/2026-08-05-universal-verifier-completion-contract.md","lastUpdated":1787407830000}'),c={name:"en/digital-employee/2026-08-05-universal-verifier-completion-contract.md"};function p(d,e,h,u,m,g){const t=s("ArticleCover");return r(),n("div",null,[o(t,{image:"/assets/covers/universal-verifier-completion-contract-cover-v2.jpg",kicker:"Digital Employee · Academic Observation 002",title:"Completion Is a Claim, Not an Accepted State",summary:"A worker may claim completion; an independent verifier and acceptance authority decide whether the claim becomes durable truth.",version:"DA002",status:"Academic Runtime V5 · 2026-08-05",languageHref:"/zh/digital-employee/2026-08-05-universal-verifier-completion-contract",languageLabel:"简体中文"}),e[0]||(e[0]=l(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Microsoft Research’s April 2026 preprint <strong>The Art of Building Verifiers for Computer Use Agents</strong> studies a difficult question at the center of computer-use automation: how can a system determine whether an Agent actually completed a task when the trajectory is long, visual, environment-dependent, and vulnerable to unsupported success claims?</p><p>The paper presents a <strong>Universal Verifier</strong> and a human-labeled benchmark, <strong>CUAVerifierBench</strong>. Its central design separates process quality from outcome attainment, distinguishes controllable from uncontrollable failures, builds task-specific non-overlapping rubrics, and retrieves screenshot evidence criterion by criterion instead of treating the last screen or the Agent’s final answer as sufficient proof.</p><p>The Research Center judgment is:</p><blockquote><p>Completion should enter a Digital Employee runtime as a versioned claim. It should become an accepted state only after independent process, outcome, failure and side-effect checks have been evaluated under an explicit authority policy.</p></blockquote><p>This supports adopting a completion-evidence contract. It does <strong>not</strong> justify adopting Microsoft’s full verifier implementation wholesale, and it does not prove transactional safety, enterprise incident reduction, or reliability outside web computer-use tasks.</p><h2 id="primary-research-object" tabindex="-1">Primary research object <a class="header-anchor" href="#primary-research-object" aria-label="Permalink to &quot;Primary research object&quot;">​</a></h2><p>The primary object is the paper, not an ordinary product announcement:</p><ul><li><strong>Title:</strong> The Art of Building Verifiers for Computer Use Agents</li><li><strong>Authors:</strong> Corby Rosset, Pratyusha Sharma, Andrew Zhao, Miguel Gonzalez-Fernandez, Ahmed Awadallah</li><li><strong>Institution:</strong> Microsoft Research, with Browserbase participation</li><li><strong>Release:</strong> arXiv v1, 5 April 2026; Microsoft Research article published 21 April 2026</li><li><strong>Open artifacts:</strong> Universal Verifier implementation and CUAVerifierBench</li></ul><p>The object entered the current Runtime queue as <code>Q-20260805-12</code>, originating from Published Research Intelligence signal <code>SIG-20260805-R-003</code>. It was selected because false-positive completion is a bounded governance problem for Digital Employees, TMPA evidence, and CodeFlowMu completion gates.</p><h2 id="what-the-universal-verifier-changes" tabindex="-1">What the Universal Verifier changes <a class="header-anchor" href="#what-the-universal-verifier-changes" aria-label="Permalink to &quot;What the Universal Verifier changes&quot;">​</a></h2><p>A conventional task judge often tries to answer one binary question: <strong>did the Agent succeed?</strong> The paper argues that this compresses several different judgments into one label.</p><p>The Universal Verifier instead models verification as a structured output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>process score</span></span>
<span class="line"><span>+ outcome decision</span></span>
<span class="line"><span>+ diagnostic failure report</span></span>
<span class="line"><span>= verifier judgment</span></span></code></pre></div><h3 id="_1-rubrics-must-be-specific-and-non-overlapping" tabindex="-1">1. Rubrics must be specific and non-overlapping <a class="header-anchor" href="#_1-rubrics-must-be-specific-and-non-overlapping" aria-label="Permalink to &quot;1. Rubrics must be specific and non-overlapping&quot;">​</a></h3><p>The rubric is generated from the task before the trajectory is shown to the scoring stage. This separation reduces the risk that criteria are invented to rationalize the Agent’s observed behavior.</p><p>The authors identify recurring rubric failures:</p><ul><li><strong>phantom criteria:</strong> grading requirements the user never requested;</li><li><strong>cascading penalties:</strong> one upstream error causes repeated downstream deductions;</li><li><strong>behavior-conditioned criteria:</strong> criteria are adapted after seeing the trajectory;</li><li><strong>unresolved conditional criteria:</strong> mutually exclusive requirements remain active together.</li></ul><p>The paper reports that improved rubric design accounted for roughly half of the observed Cohen’s kappa gain during iterative development. This matters because a powerful scorer cannot reliably repair a defective measurement contract downstream.</p><h3 id="_2-process-and-outcome-are-independent-signals" tabindex="-1">2. Process and outcome are independent signals <a class="header-anchor" href="#_2-process-and-outcome-are-independent-signals" aria-label="Permalink to &quot;2. Process and outcome are independent signals&quot;">​</a></h3><p>The process score evaluates how well the Agent executed applicable sub-goals. The outcome decision asks whether a reasonable user would regard the requested end state as achieved.</p><p>They may disagree legitimately:</p><ul><li>an Agent follows the correct process but is blocked by a CAPTCHA or unavailable inventory;</li><li>an Agent reaches the requested outcome through an unexpected valid route;</li><li>an Agent produces a plausible final answer but skipped required actions;</li><li>an Agent completes the visible goal while causing an unsolicited side effect.</li></ul><p>For a Digital Employee, this distinction prevents two opposite errors: accepting effort as completion, or treating an environment-caused blocker as evidence of worker misconduct.</p><h3 id="_3-failure-responsibility-is-a-first-class-result" tabindex="-1">3. Failure responsibility is a first-class result <a class="header-anchor" href="#_3-failure-responsibility-is-a-first-class-result" aria-label="Permalink to &quot;3. Failure responsibility is a first-class result&quot;">​</a></h3><p>The verifier separates factors under the Agent’s control from factors outside it.</p><p>Controllable failures include intent mismatch, reasoning errors, hallucinations, insufficient effort, execution mistakes, and invalid tool interaction. Uncontrollable failures include login walls without credentials, CAPTCHAs, infrastructure failure, unavailable entities, sold-out inventory, and the absence of matching results.</p><p>This classification is not merely explanatory. It affects process scoring, retry policy, escalation, and whether the system should improve the worker, repair the environment, request authority, or terminate the task.</p><h3 id="_4-evidence-retrieval-is-criterion-specific" tabindex="-1">4. Evidence retrieval is criterion-specific <a class="header-anchor" href="#_4-evidence-retrieval-is-criterion-specific" aria-label="Permalink to &quot;4. Evidence retrieval is criterion-specific&quot;">​</a></h3><p>Long trajectories can contain hundreds of screenshots. Passing all frames into one prompt produces a needle-in-a-haystack problem; inspecting only the last frames can miss critical evidence.</p><p>The Universal Verifier creates a screenshot-by-criterion relevance matrix. For each rubric criterion, it selects the most relevant screenshots, extracts evidence, resolves conditional criteria, performs a reality check, and then rescores the rubric. Screenshot evidence takes precedence over the Agent’s own completion statement.</p><p>This is an important architectural pattern: evidence should be indexed against claims, not merely accumulated in a chronological log.</p><p><img src="`+i+`" alt="Completion claim, independent verifier, acceptance gate and accepted state"></p><p><em>Diagram: joinwell52 Research Center synthesis of the paper’s verifier boundary and the proposed Digital Employee acceptance boundary.</em></p><h2 id="experimental-evidence" tabindex="-1">Experimental evidence <a class="header-anchor" href="#experimental-evidence" aria-label="Permalink to &quot;Experimental evidence&quot;">​</a></h2><p>The paper evaluates verifier–human agreement on two paper-era splits:</p><table tabindex="0"><thead><tr><th>Measure</th><th style="text-align:right;">Internal, n=140</th><th style="text-align:right;">Browserbase OM2W, n=106</th></tr></thead><tbody><tr><td>Universal Verifier outcome Cohen’s κ</td><td style="text-align:right;">0.64</td><td style="text-align:right;">0.58</td></tr><tr><td>WebJudge outcome Cohen’s κ</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.26</td></tr><tr><td>WebVoyager outcome Cohen’s κ</td><td style="text-align:right;">0.31</td><td style="text-align:right;">0.13</td></tr><tr><td>Universal Verifier outcome false-positive rate</td><td style="text-align:right;">0.01</td><td style="text-align:right;">0.08</td></tr><tr><td>WebJudge outcome false-positive rate</td><td style="text-align:right;">0.22</td><td style="text-align:right;">0.40</td></tr><tr><td>WebVoyager outcome false-positive rate</td><td style="text-align:right;">0.45</td><td style="text-align:right;">0.60</td></tr><tr><td>Universal Verifier process Cohen’s κ</td><td style="text-align:right;">0.59</td><td style="text-align:right;">0.43</td></tr></tbody></table><p>The external false-positive rate is <strong>8 percent</strong>, so “near zero” must not be interpreted as literal zero. The result is nevertheless materially lower than the evaluated baselines.</p><p>The paper also upgrades baseline verifier backbones to GPT-5.2. A stronger model reduces false positives in some settings, but increases false negatives and produces only modest overall kappa improvement. The authors therefore attribute the main advantage to the verifier architecture rather than model substitution alone.</p><p>The Browserbase human inter-annotator ranges were reported as 0.53–0.57 for outcome and 0.36–0.45 for process. The Universal Verifier’s agreement falls within those ranges, which supports the bounded statement that it agrees with humans about as often as the annotators agree with one another. It does not establish that either humans or the verifier are an objective oracle.</p><h3 id="version-note" tabindex="-1">Version note <a class="header-anchor" href="#version-note" aria-label="Permalink to &quot;Version note&quot;">​</a></h3><p>The paper reports an internal experimental split of 140 trajectories. The currently published Hugging Face dataset card lists 154 internal trajectories and 106 Browserbase trajectories. Results must therefore be bound to the exact paper, dataset configuration, split and release rather than described as timeless properties of “CUAVerifierBench.”</p><h2 id="why-the-result-is-architectural" tabindex="-1">Why the result is architectural <a class="header-anchor" href="#why-the-result-is-architectural" aria-label="Permalink to &quot;Why the result is architectural&quot;">​</a></h2><p>The paper’s most transferable insight is decomposition, not a specific prompt or model:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker claim</span></span>
<span class="line"><span>→ claim-specific evidence retrieval</span></span>
<span class="line"><span>→ process assessment</span></span>
<span class="line"><span>→ outcome readback</span></span>
<span class="line"><span>→ failure and side-effect classification</span></span>
<span class="line"><span>→ policy/authority decision</span></span>
<span class="line"><span>→ accepted completion receipt</span></span></code></pre></div><p>A Digital Employee should not be both claimant and final acceptor. The worker may produce a completion claim, evidence references, and a proposed status. An independent verifier should evaluate those claims. A policy or authorized human should retain the ability to accept, reject, escalate, or leave the result undetermined.</p><p>This mirrors a separation-of-duties principle:</p><ul><li><strong>Worker:</strong> performs the operation and submits evidence.</li><li><strong>Verifier:</strong> evaluates evidence against a versioned contract.</li><li><strong>Acceptor:</strong> applies business authority and risk policy.</li><li><strong>Runtime:</strong> records all judgments without erasing disagreement.</li></ul><h2 id="proposed-completion-evidence-contract" tabindex="-1">Proposed completion evidence contract <a class="header-anchor" href="#proposed-completion-evidence-contract" aria-label="Permalink to &quot;Proposed completion evidence contract&quot;">​</a></h2><p>A reusable runtime projection could be:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">completion_claim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  claim_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  operation_node_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  claimant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  requested_outcome</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rubric_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  process_evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  outcome_evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  deterministic_checks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  learned_verifier_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  failure_class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  controllability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  side_effect_assessment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  verifier_identity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  verifier_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  acceptance_authority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  acceptance_decision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">accepted | rejected | escalated | undetermined</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  accepted_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_receipt_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>The portable contract should reference raw screenshots, traces and business-system readbacks rather than embedding all sensitive evidence directly. Retention, privacy and access controls belong to governed evidence storage.</p><h2 id="what-should-remain-independent" tabindex="-1">What should remain independent <a class="header-anchor" href="#what-should-remain-independent" aria-label="Permalink to &quot;What should remain independent&quot;">​</a></h2><p>A consequential Digital Employee runtime should compose at least three verification surfaces:</p><ol><li><strong>Deterministic checks</strong> — database readback, file hash, workflow status, balance, record existence, or application state.</li><li><strong>Learned verification</strong> — trajectory interpretation, screenshot evidence, intent alignment, failure diagnosis, and side-effect detection.</li><li><strong>Human or policy acceptance</strong> — authority for irreversible, ambiguous, regulated, or high-impact work.</li></ol><p>These checks may disagree. The runtime should preserve the conflict instead of forcing an immediate binary answer. <code>Undetermined</code> or <code>Needs Human Acceptance</code> is safer than manufacturing <code>Completed</code>.</p><h2 id="limitations-and-counter-evidence" tabindex="-1">Limitations and counter-evidence <a class="header-anchor" href="#limitations-and-counter-evidence" aria-label="Permalink to &quot;Limitations and counter-evidence&quot;">​</a></h2><p>The publication gate must retain the following boundaries:</p><ul><li>The source is an arXiv preprint and official research publication, not a final peer-reviewed archival result.</li><li>The paper’s human-labeled datasets are small.</li><li>The Browserbase split contains trajectories from one Agent, Fara-7B; transfer to other Agents is not established.</li><li>The work is restricted to web computer-use trajectories.</li><li>Human labels are judgments, not an objective completion oracle.</li><li>The Universal Verifier is a large bundled system of code and prompts; independent transfer value is not proven for every component.</li><li>The paper does not demonstrate rollback, compensation, idempotency, persistent-session recovery, delayed side-effect detection, or transactional guarantees.</li><li>Cost, latency, privacy, screenshot retention, and enterprise access boundaries are not resolved.</li><li>The current dataset card warns that the 106-task external corpus is relatively small and inherits Online-Mind2Web’s temporal and domain biases.</li></ul><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>No TMPA Core change is justified by one paper. A profile or projection may later represent claimant, verifier, acceptor, evidence contract, process judgment, outcome judgment, failure class and conflicting decision. The portable protocol should carry references and deterministic semantics, not vendor-specific verifier prompts.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>Each consequential Operation Node should emit a completion claim rather than directly writing accepted completion. Position and WorkOrder definitions should specify expected business outcome, verifier requirements, acceptance authority, prohibited side effects, retry policy and escalation rules.</p><p>Uncontrollable failure should remain distinct from worker failure. A correct process blocked by missing credentials or unavailable inventory is not successful work, but it is also not equivalent to hallucination or negligent execution.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>The immediate engineering step is a durable <strong>completion receipt projection</strong>, not a general visual verifier. CodeFlowMu can first compose:</p><ul><li>deterministic post-action readback;</li><li>versioned evidence references;</li><li>optional learned verification;</li><li>QA/EVAL or ADMIN acceptance;</li><li>explicit conflict and escalation states;</li><li>commit and artifact verification before terminal completion.</li></ul><p>A worker’s last action, final message, or screenshot should never alone move a consequential task to <code>done</code>.</p><h2 id="publication-judgment" tabindex="-1">Publication judgment <a class="header-anchor" href="#publication-judgment" aria-label="Permalink to &quot;Publication judgment&quot;">​</a></h2><p>The evidence supports this bounded adoption:</p><blockquote><p>Adopt the separation pattern—claim, process evidence, outcome evidence, failure attribution, independent verification and authority-based acceptance. Do not treat the reported Universal Verifier as a universal production guarantee.</p></blockquote><p>The paper provides strong evidence that binary self-reported completion is structurally inadequate. It provides medium-strength evidence that rubric-grounded visual verification can transfer into broader Digital Employee systems. It provides weak evidence about enterprise incident reduction, non-web work and transactional safety.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Rosset et al., <strong>The Art of Building Verifiers for Computer Use Agents</strong>, arXiv: <a href="https://arxiv.org/abs/2604.06240" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.06240</a></li><li>Full experimental HTML: <a href="https://arxiv.org/html/2604.06240" target="_blank" rel="noreferrer">https://arxiv.org/html/2604.06240</a></li><li>Microsoft Research publication: <a href="https://www.microsoft.com/en-us/research/publication/the-art-of-building-verifiers-for-computer-use-agents/" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/research/publication/the-art-of-building-verifiers-for-computer-use-agents/</a></li><li>Microsoft Research technical article: <a href="https://www.microsoft.com/en-us/research/articles/the-art-of-building-verifiers-for-computer-use-agents/" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/research/articles/the-art-of-building-verifiers-for-computer-use-agents/</a></li><li>Universal Verifier implementation and Fara repository: <a href="https://github.com/microsoft/fara" target="_blank" rel="noreferrer">https://github.com/microsoft/fara</a></li><li>CUAVerifierBench dataset card: <a href="https://huggingface.co/datasets/microsoft/CUAVerifierBench" target="_blank" rel="noreferrer">https://huggingface.co/datasets/microsoft/CUAVerifierBench</a></li><li>Runtime queue object: <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/plans/2026/08/2026-08-05-plan.json" target="_blank" rel="noreferrer">https://github.com/joinwell52-AI/joinwell52/blob/main/research/runtime/plans/2026/08/2026-08-05-plan.json</a></li></ol>`,75))])}const k=a(c,[["render",p]]);export{v as __pageData,k as default};
